package com.herbpatch;

import lombok.AllArgsConstructor;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

import java.awt.*;

@ConfigGroup(HerbPatchConfig.CONFIG_GROUP)
public interface HerbPatchConfig extends Config {
    String CONFIG_GROUP = "herbpatchoverlay";

    @ConfigItem(
        keyName = "overlaySelector",
        name = "Overlay type",
        description = "Configure overlay type",
        position = 101
    )
    default OverlayType overlaySelector() {
        return OverlayType.HULL;
    }

    @ConfigItem(
        keyName = "renderIfOvergrown",
        name = "Render overgrown overlay",
        description = "Render overlay on overgrown herb patches",
        position = 102
    )
    default boolean renderIfOvergrown() {
        return true;
    }

    @ConfigItem(
        keyName = "renderIfEmpty",
        name = "Render empty overlay",
        description = "Render overlay on empty herb patches",
        position = 103
    )
    default boolean renderIfEmpty() {
        return true;
    }


    @ConfigSection(
        name = "Render Options",
        description = "Options relating to rendering",
        position = 200
    )
    String renderOptionsSection = "optionsOutline";

    @ConfigItem(
        keyName = "outlineThickness",
        name = "Outline Thickness",
        description = "Outline thickness for overlay type Outline",
        section = renderOptionsSection,
        position = 201
    )
    default int outlineThickness() {
        return 2;
    }

    @ConfigItem(
        keyName = "outlineFeather",
        name = "Outline Feather",
        description = "Outline feather for overlay type Outline",
        section = renderOptionsSection,
        position = 202
    )
    default int outlineFeather() {
        return 0;
    }

    @ConfigItem(
        keyName = "fillAlpha",
        name = "Hull/Tile Fill Alpha",
        description = "Fill alpha for overlay type Hull and Tile",
        section = renderOptionsSection,
        position = 203
    )
    default int fillAlpha() {
        return 10;
    }

    @ConfigSection(
            name = "Herb Overlay Color",
            description = "Custom overlay colors for herbs",
            position = 300
    )
    String customColorSection = "customColor";

    @ConfigItem(
            keyName = "overgrownColor",
            name = "Overgrown",
            description = "",
            section = customColorSection,
            position = 301
    )
    default Color overgrownColor() {
        return Color.RED;
    }

    @ConfigItem(
            keyName = "emptyColor",
            name = "Empty",
            description = "",
            section = customColorSection,
            position = 302
    )
    default Color emptyColor() {
        return Color.RED;
    }

    @ConfigItem(
            keyName = "unripeColor",
            name = "Unripe",
            description = "",
            section = customColorSection,
            position = 303
    )
    default Color unripeColor() {
        return Color.YELLOW;
    }

    @ConfigItem(
            keyName = "matureColor",
            name = "Mature",
            description = "",
            section = customColorSection,
            position = 304
    )
    default Color matureColor() {
        return Color.GREEN;
    }

    @ConfigItem(
            keyName = "diseasedColor",
            name = "Diseased",
            description = "",
            section = customColorSection,
            position = 305
    )
    default Color diseasedColor() {
        return Color.MAGENTA;
    }

    @ConfigItem(
            keyName = "deadColor",
            name = "Dead",
            description = "",
            section = customColorSection,
            position = 306
    )
    default Color deadColor() {
        return Color.RED;
    }

    @AllArgsConstructor
    enum OverlayType {
        HULL("Hull"),
        OUTLINE("Outline"),
        TILE("Tile");

        private final String value;

        @Override
        public String toString() {
            return value;
        }
    }
}

package com.herbpatch.constants;

import java.util.Arrays;
import java.util.Map;
import java.util.stream.Collectors;

import static net.runelite.api.gameval.ObjectID.*;
// Transmog controllers for various farming patches
import static net.runelite.api.gameval.VarbitID.FARMING_TRANSMIT_A; // Troll Stronghold, Weiss
import static net.runelite.api.gameval.VarbitID.FARMING_TRANSMIT_B; // Harmony Island
import static net.runelite.api.gameval.VarbitID.FARMING_TRANSMIT_D; // Falador, Port Phasmatys, Hosidius, Ardougne, Catherby, Varlamore
import static net.runelite.api.gameval.VarbitID.FARMING_TRANSMIT_E; // Farming Guild

/**
 * Enum containing ObjectIDs and VarbitIDs for the various herb patches around Gilenor
 */
public enum HerbPatch {
    FALADOR    (FARMING_HERB_PATCH_1,  FARMING_TRANSMIT_D),
    CATHERBY   (FARMING_HERB_PATCH_2,  FARMING_TRANSMIT_D),
    ARDOUGNE   (FARMING_HERB_PATCH_3,  FARMING_TRANSMIT_D),
    PHASMATYS  (FARMING_HERB_PATCH_4,  FARMING_TRANSMIT_D),
    HARMONY    (FARMING_HERB_PATCH_5,  FARMING_TRANSMIT_B),
    STRONGHOLD (MYARM_HERBPATCH,       FARMING_TRANSMIT_A),
    HOSIDIUS   (FARMING_HERB_PATCH_6,  FARMING_TRANSMIT_D),
    WEISS      (MY2ARM_HERBPATCH_FAKE, FARMING_TRANSMIT_A),
    GUILD      (FARMING_HERB_PATCH_7,  FARMING_TRANSMIT_E),
    VARLAMORE  (FARMING_HERB_PATCH_8,  FARMING_TRANSMIT_D);

    public final int objectId;
    public final int varbit;

    HerbPatch(int objectId, int varbit) {
        this.objectId = objectId;
        this.varbit = varbit;
    }

    private static final Map<Integer, HerbPatch> BY_ID = Arrays.stream(values()).collect(Collectors.toMap(p -> p.objectId, p -> p));

    public static HerbPatch byObjectId(int id) {
        return BY_ID.get(id);
    }
}

package com.herbpatch.constants;

import lombok.extern.slf4j.Slf4j;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Enum representing stages of growth for herbs.
 * Each enum corresponds to a specific stage of growth and includes all varbit values associated with that stage.
 *
 * @see <a href="https://oldschool.runescape.wiki/w/Bucket:Varbit">Varbit index</a>
 */
@Slf4j
public enum HerbStages {
    OVERGROWN(0, 1, 2),
    EMPTY(3),
    GROWN(8,9,10,15,16,17,22,23,24,29,30,31,36,37,38,43,44,45,50,51,52,57,58,59,72,73,74,79,80,81,86,87,88,93,94,95,100,101,102,107,108,109),
    DISEASED(128,129,130,131,132,133,134,135,136,137,138,139,140,141,142,143,144,145,146,147,148,149,150,151,152,153,154,155,156,157,158,159,160,161,162,163,164,165,166,167,168,169),
    DEAD(170,171,172),
    GROWING;

    // Build HashMap for lookups during rendering
    private static final Map<Integer, HerbStages> BY_STATE;
    static {
        Map<Integer, HerbStages> map = new HashMap<>();
        for (HerbStages stage : values()) {
            for (int n : stage.numbers) {
                map.put(n, stage);
            }
        }
        BY_STATE = Collections.unmodifiableMap(map);
    }

    private final int[] numbers;

    HerbStages(int... numbers) {
        this.numbers = numbers;
    }

    /**
     * Get the enum corresponding to a given varbit number
     * @param number The varbit number
     * @return The corresponding enum
     */
    public static HerbStages getHerbStage(int number) {
        return BY_STATE.getOrDefault(number, GROWING);
    }
}

package com.herbpatch;

import com.google.inject.Provides;
import com.herbpatch.constants.HerbPatch;
import lombok.AccessLevel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;

@Slf4j
@PluginDescriptor(
    name = "Herb Patch Overlay",
    description = "Renders colored overlays on herb patches depending on the state of growth",
    tags = { "herblore", "farming", "timer" }
)
public class HerbPatchPlugin extends Plugin {
    @Inject private OverlayManager overlayManager;
    @Inject private HerbPatchOverlay herbOverlay;

    @Getter(AccessLevel.PACKAGE)
    private GameObject herbPatchObject;

    @Provides
    HerbPatchConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(HerbPatchConfig.class);
    }

    @Override
    protected void startUp() {
        // Add HerbPatchOverlay to OverlayManager at start up
        overlayManager.add(herbOverlay);
    }

    @Override
    protected void shutDown() {
        overlayManager.remove(herbOverlay);
        herbPatchObject = null;
    }

    @Subscribe
    public void onGameObjectSpawned(GameObjectSpawned event) {
        HerbPatch patch = HerbPatch.byObjectId(event.getGameObject().getId());
        if (patch == null) return;

        herbPatchObject = event.getGameObject();
        log.debug("Herb patch [{}] spawned", herbPatchObject.getId());
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        // When changing state (e.g. teleporting) clear herb object
        if (event.getGameState() == GameState.LOADING) {
            herbPatchObject = null;
        }
    }
}

package com.herbpatch;

import com.herbpatch.constants.HerbPatch;
import com.herbpatch.constants.HerbStages;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

import javax.inject.Inject;
import java.awt.*;
import java.util.Objects;

public class HerbPatchOverlay extends Overlay {
    private static final int MAX_DISTANCE = 2500;
    private static final int OVERLAY_PRIORITY = 0;

    private final Client client;
    private final HerbPatchPlugin plugin;
    private final ModelOutlineRenderer modelOutlineRenderer;

    @Inject private HerbPatchConfig config;

    @Inject
    private HerbPatchOverlay(Client client, HerbPatchPlugin plugin, ModelOutlineRenderer modelOutlineRenderer) {
        this.plugin = plugin;
        this.client = client;
        this.modelOutlineRenderer = modelOutlineRenderer;
        setPosition(OverlayPosition.DYNAMIC);
        setPriority(OVERLAY_PRIORITY);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        GameObject patchObject = plugin.getHerbPatchObject();
        if (Objects.isNull(patchObject)) {
            return null;
        }

        HerbPatch patch = HerbPatch.byObjectId(patchObject.getId());
        if (patch == null) return null;

        int state = client.getVarbitValue(patch.varbit);

        // If state is not default and user wants to render for current state -> render overlay
        if (state != -1) {
            Color color = getHerbOverlayColor(state);
            if (!Objects.isNull(color)) {
                drawOverlay(patchObject, graphics, color);
            }
        }

        return null;
    }

    /**
     * Method to draw object overlay on screen. Should be run every frame.
     * @param object Object to draw overlay on/above
     * @param graphics Main Java AWT 2D graphics object
     * @param color Overlay main outline color
     */
    private void drawOverlay(GameObject object, Graphics2D graphics, Color color) {
        // Get player location and herb patch location
        LocalPoint herbLocation = object.getLocalLocation();
        LocalPoint playerLocation = client.getLocalPlayer().getLocalLocation();
        if (Objects.isNull(playerLocation)) {
            return;
        }

        // Check if herb patch is within set max distance
        if (playerLocation.distanceTo(herbLocation) <= MAX_DISTANCE) {
            Shape herb;
            // Set the overlay shape (object hull or tile)
            switch (config.overlaySelector()) {
                case TILE:
                    herb = Perspective.getCanvasTilePoly(client, herbLocation, object.getPlane());
                    break;
                case OUTLINE:
                    modelOutlineRenderer.drawOutline(object, config.outlineThickness(), color, config.outlineFeather());
                    return;
                case HULL:
                    herb = object.getConvexHull();
                    break;
                default:
                    return;
            }

            Point mousePosition = client.getMouseCanvasPosition();
            if (herb != null) {
                // Check if user is hovering the herb
                if (herb.contains(mousePosition.getX(), mousePosition.getY())) {
                    // Darken color if pointer is hovering herb
                    graphics.setColor(color.darker());
                } else {
                    graphics.setColor(color);
                }

                // Render overlay
                graphics.draw(herb);
                graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), config.fillAlpha()));
                graphics.fill(herb);
            }
        }
    }

    /**
     * Get the appropriate color based on herb state.
     * @param state The server controlled integer representing the state of the herb
     * @return The color to render the overlay
     * @see HerbStages
     */
    private Color getHerbOverlayColor(int state) {
        switch (HerbStages.getHerbStage(state)) {
            case OVERGROWN:
                if (config.renderIfOvergrown()) {
                    return config.overgrownColor();
                }
                return null;
            case EMPTY:
                if (config.renderIfEmpty()) {
                    return config.emptyColor();
                }
                return null;
            case GROWING:
                return config.unripeColor();
            case GROWN:
                return config.matureColor();
            case DISEASED:
                return config.diseasedColor();
            case DEAD:
                return config.deadColor();
            default:
                return null;
        }
    }
}
